// Episode timing, generated by scripts/build-timeline.mjs from the narration durations.
import timeline from './timeline.json';
import narration from './narration.json';
import durations from './vo-durations.json';

export const FPS = timeline.fps;
export const TOTAL = timeline.total;
export const SCENES = timeline.scenes;
export type VoId = keyof typeof timeline.vo;

const DUR = durations as Record<string, number>;
const SAY = Object.fromEntries(narration.lines.map((l) => [l.id, l.say.replace(/[{}]/g, '')]));

export const scene = (id: number) => SCENES.find((s) => s.id === id)!;
export const vo = (id: VoId) => timeline.vo[id];
export const voEnd = (id: VoId) => timeline.vo[id] + Math.ceil(DUR[id] * FPS);

/** Approximate global frame at which `word` is spoken in a line. */
export const wordAt = (id: VoId, word: string) => {
  const s = SAY[id].toLowerCase();
  const i = s.indexOf(word.toLowerCase());
  return Math.round(vo(id) + (i < 0 ? 0 : i / s.length) * DUR[id] * FPS);
};

/** Converts a global (actual) frame into a scene's design frame (Phase 3 choreography). */
export const dF = (sceneId: number, globalFrame: number) => {
  const s = scene(sceneId);
  return (globalFrame - s.from) / s.k;
};

export type Line = {id: VoId; scene: number; sub: string; from: number; to: number};
export const LINES: Line[] = narration.lines.map((l) => ({
  id: l.id as VoId,
  scene: l.scene,
  sub: l.sub,
  from: vo(l.id as VoId),
  to: voEnd(l.id as VoId),
}));
